<parameter name="content">import csv


def column_means(path, encoding="utf-8-sig"):
    """讀取 CSV 檔，回傳 {欄名: 平均值}。

    - 第一列視為欄位名稱。
    - 空白或無法轉成數字的儲存格會被略過。
    - 整欄都沒有數值時，該欄平均值為 None。
    """
    sums = {}
    counts = {}

    with open(path, newline="", encoding=encoding) as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            return {}
        for name in reader.fieldnames:
            sums[name] = 0.0
            counts[name] = 0

        for row in reader:
            for name in reader.fieldnames:
                value = row.get(name)
                if value is None or value.strip() == "":
                    continue
                try:
                    sums[name] += float(value)
                    counts[name] += 1
                except ValueError:
                    continue  # 非數值（例如文字欄）直接略過

    return {
        name: (sums[name] / counts[name] if counts[name] else None)
        for name in sums
    }


if __name__ == "__main__":
    import sys

    if len(sys.argv) != 2:
        sys.exit("用法: python csv_column_means.py <檔案.csv>")
    for col, mean in column_means(sys.argv[1]).items():
        print(f"{col}: {mean}")
